CREATE DATABASE IF NOT EXISTS huit_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE huit_db;
CREATE TABLE IF NOT EXISTS branches (id INT AUTO_INCREMENT PRIMARY KEY, branch_name VARCHAR(150) NOT NULL, address VARCHAR(255) NOT NULL);
CREATE TABLE IF NOT EXISTS teachers (id INT AUTO_INCREMENT PRIMARY KEY, full_name VARCHAR(150) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, phone VARCHAR(30) NOT NULL, expertise VARCHAR(255) NOT NULL, password_hash VARCHAR(255) NOT NULL);
CREATE TABLE IF NOT EXISTS schedules (id INT AUTO_INCREMENT PRIMARY KEY, teacher_id INT NOT NULL, branch_id INT NOT NULL, subject_name VARCHAR(150) NOT NULL, room VARCHAR(100) NOT NULL, day_of_week TINYINT NOT NULL, start_period TINYINT NOT NULL, end_period TINYINT NOT NULL, start_date DATE NOT NULL, end_date DATE NOT NULL, FOREIGN KEY (teacher_id) REFERENCES teachers(id), FOREIGN KEY (branch_id) REFERENCES branches(id));
CREATE TABLE IF NOT EXISTS admins (id INT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(100) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL);
